import json
d = json.load(open('/Users/stephenhe/Projects/capybara-benchmark/projects/keystone/UI_GRAPH.json'))
node_ids = {n['id'] for n in d['nodes']}

# Check all edge from/to reference valid nodes
issues = []
for edge in d['edges']:
    frm = edge['from']
    to = edge['to']
    # Normalize - check if the base route matches a node
    if frm not in node_ids:
        issues.append(f'  Edge from unknown: {frm}')
    if to not in node_ids:
        issues.append(f'  Edge to unknown: {to}')

if issues:
    print('ISSUES:')
    for i in issues:
        print(i)
else:
    print('All edge endpoints reference valid node IDs')
"

